CREATE OR REPLACE FUNCTION public.finance_bank_unpaid_draft(t uuid,txn uuid,items jsonb,notes text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bank_transactions;ba bank_accounts;x jsonb;iv invoices;eb expense_bills;amt numeric;total numeric:=0;ap uuid;ls jsonb:='[]';sources jsonb:='[]';ident uuid;BEGIN IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('finance-bank:'||t::text,0));SELECT * INTO b FROM bank_transactions WHERE tenant_id=t AND id=txn FOR UPDATE;IF NOT FOUND OR b.money_out<=0 OR b.money_in<>0 OR b.matched_record_id IS NOT NULL OR EXISTS(SELECT 1 FROM bank_transaction_matches WHERE tenant_id=t AND txn_id=b.id) THEN RAISE EXCEPTION 'Unmatched outgoing bank line required';END IF;PERFORM finance_assert_open(t,b.txn_date);IF jsonb_typeof(items) IS DISTINCT FROM 'array' OR jsonb_array_length(items)<1 OR jsonb_array_length(items)>50 OR EXISTS(SELECT 1 FROM jsonb_array_elements(items) i GROUP BY i->>'source',i->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Select distinct unpaid items';END IF;SELECT * INTO ba FROM bank_accounts WHERE tenant_id=t AND id=b.bank_account_id AND is_active;IF ba.id IS NULL OR ba.linked_gl_account_id IS NULL THEN RAISE EXCEPTION 'Bank account must be linked to books';END IF;SELECT id INTO ap FROM chart_of_accounts WHERE tenant_id=t AND code='2000' AND is_active;
FOR x IN SELECT * FROM jsonb_array_elements(items) LOOP amt:=(x->>'amount')::numeric;IF amt IS NULL OR amt<=0 OR amt<>round(amt,2) THEN RAISE EXCEPTION 'Positive cents amount required';END IF;
IF x->>'source'='supplier' THEN SELECT * INTO iv FROM invoices WHERE tenant_id=t AND id=(x->>'id')::uuid FOR UPDATE;IF iv.id IS NULL OR iv.review_status IS DISTINCT FROM 'Approved' OR iv.invoice_date>b.txn_date OR iv.payment_status='voided' OR amt>greatest(0,iv.total_amount-coalesce(iv.amount_paid,0)-coalesce(iv.held_amount,0)) THEN RAISE EXCEPTION 'Invoice changed or not payable';END IF;sources:=sources||jsonb_build_array(jsonb_build_object('source','supplier','id',iv.id,'fingerprint',md5(to_jsonb(iv)::text)));
ELSIF x->>'source'='bill' THEN SELECT * INTO eb FROM expense_bills WHERE tenant_id=t AND id=(x->>'id')::uuid FOR UPDATE;IF eb.id IS NULL OR eb.approval_status<>'posted' OR eb.bill_date>b.txn_date OR amt>eb.total_amount-eb.paid_amount THEN RAISE EXCEPTION 'Bill changed or not payable';END IF;sources:=sources||jsonb_build_array(jsonb_build_object('source','bill','id',eb.id,'fingerprint',md5(to_jsonb(eb)::text)));
ELSE RAISE EXCEPTION 'Choose supplier invoices or bills only';END IF;total:=total+amt;END LOOP;IF total<>b.money_out THEN RAISE EXCEPTION 'Selected total must equal bank amount';END IF;
ls:=jsonb_build_array(jsonb_build_object('account_id',ap,'debit',total,'credit',0),jsonb_build_object('account_id',ba.linked_gl_account_id,'debit',0,'credit',total));ident:=finance_schedule_enqueue(t,b.txn_date,'bank_payment','Bank payment · selected unpaid items','Owner-confirmed bank statement evidence; payment awaits monthly approval','bank-payment:'||txn,ls,jsonb_build_object('bank',b.id,'bank_fingerprint',md5(to_jsonb(b)::text),'items',items,'sources',sources,'notes',left(notes,3000)));RETURN ident;END $$;
REVOKE ALL ON FUNCTION public.finance_bank_unpaid_draft(uuid,uuid,jsonb,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_bank_unpaid_draft(uuid,uuid,jsonb,text) TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;IF position('INSERT INTO journal_entries(tenant_id' IN def)=0 THEN RAISE EXCEPTION 'Approval anchor unavailable';END IF;def:=replace(def,'DECLARE q finance_entry_drafts;','DECLARE bp bank_transactions; bx jsonb; br jsonb; bm jsonb; checkstamp text; q finance_entry_drafts;');def:=replace(def,'INSERT INTO journal_entries(tenant_id','IF q.kind=''bank_payment'' THEN PERFORM pg_advisory_xact_lock(hashtextextended(''finance-bank:''||t::text,0));SELECT * INTO bp FROM bank_transactions WHERE tenant_id=t AND id=(q.source_data->>''bank'')::uuid FOR UPDATE;IF bp.id IS NULL OR md5(to_jsonb(bp)::text) IS DISTINCT FROM q.source_data->>''bank_fingerprint'' THEN RAISE EXCEPTION ''Bank source changed; cancel and prepare again'';END IF;FOR bx IN SELECT * FROM jsonb_array_elements(q.source_data->''sources'') LOOP IF bx->>''source''=''supplier'' THEN SELECT md5(to_jsonb(i)::text) INTO checkstamp FROM invoices i WHERE tenant_id=t AND id=(bx->>''id'')::uuid FOR UPDATE;ELSE SELECT md5(to_jsonb(i)::text) INTO checkstamp FROM expense_bills i WHERE tenant_id=t AND id=(bx->>''id'')::uuid FOR UPDATE;END IF;IF checkstamp IS DISTINCT FROM bx->>''fingerprint'' THEN RAISE EXCEPTION ''Unpaid source changed; cancel and prepare again'';END IF;END LOOP;SELECT public.finance_record_owed_payment(t,bp.txn_date,''bank_transfer'',bp.bank_account_id,bp.money_out,coalesce(bp.reference,''''),q.source_data->''items'') INTO br;SELECT jsonb_agg(jsonb_build_object(''type'',CASE WHEN value->>''source''=''supplier'' THEN ''payment'' ELSE ''bill_payment'' END,''id'',value->>''id'')) INTO bm FROM jsonb_array_elements(br);PERFORM public.finance_confirm_bank_matches(t,bp.id,bm,coalesce(q.source_data->>''notes'',''''));UPDATE finance_entry_drafts SET status=''approved'',approved_by=auth.uid(),approved_at=now() WHERE tenant_id=t AND id=q.id;RETURN NULL;END IF; INSERT INTO journal_entries(tenant_id');EXECUTE def;END $$;